	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/cv/review", wrapper.RequestCvReview)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/agent/cv", wrapper.AgentGetCv)
