// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// AgentCreateApplication Gefundene Stelle als Vorgemerkt anlegen
	// (POST /api/agent/applications)
	AgentCreateApplication(ctx context.Context, request AgentCreateApplicationRequestObject) (AgentCreateApplicationResponseObject, error)
	// AgentGetCv Gespeicherter Lebenslauf (404, solange keiner gespeichert ist)
	// (GET /api/agent/cv)
	AgentGetCv(ctx context.Context, request AgentGetCvRequestObject) (AgentGetCvResponseObject, error)
	// AgentListCvReviews Optimierungen in einem Zustand (für den Agenten meist „angefordert“)
	// (GET /api/agent/cv-reviews)
	AgentListCvReviews(ctx context.Context, request AgentListCvReviewsRequestObject) (AgentListCvReviewsResponseObject, error)
	// AgentCompleteCvReview Vorschlag und Hinweise abliefern (409, wenn nicht angefordert)
	// (PUT /api/agent/cv-reviews/{id})
	AgentCompleteCvReview(ctx context.Context, request AgentCompleteCvReviewRequestObject) (AgentCompleteCvReviewResponseObject, error)

	// (GET /api/v1/applications)
	ListApplications(ctx context.Context, request ListApplicationsRequestObject) (ListApplicationsResponseObject, error)
	// CreateApplication Bewerbung inklusive erstem Ereignis (Vorgemerkt oder Beworben) anlegen
	// (POST /api/v1/applications)
	CreateApplication(ctx context.Context, request CreateApplicationRequestObject) (CreateApplicationResponseObject, error)

	// (DELETE /api/v1/applications/{id})
	DeleteApplication(ctx context.Context, request DeleteApplicationRequestObject) (DeleteApplicationResponseObject, error)

	// (GET /api/v1/applications/{id})
	GetApplication(ctx context.Context, request GetApplicationRequestObject) (GetApplicationResponseObject, error)
	// UpdateApplication Stammdaten ändern (nicht den Status)
	// (PATCH /api/v1/applications/{id})
	UpdateApplication(ctx context.Context, request UpdateApplicationRequestObject) (UpdateApplicationResponseObject, error)

	// (GET /api/v1/applications/{id}/allowed-events)
	ListAllowedEvents(ctx context.Context, request ListAllowedEventsRequestObject) (ListAllowedEventsResponseObject, error)
	// AddEvent Statuswechsel als Ereignis erfassen (422 bei unerlaubtem Übergang)
	// (POST /api/v1/applications/{id}/events)
	AddEvent(ctx context.Context, request AddEventRequestObject) (AddEventResponseObject, error)
	// UndoLastEvent Letztes Ereignis rückgängig machen
	// (DELETE /api/v1/applications/{id}/events/latest)
	UndoLastEvent(ctx context.Context, request UndoLastEventRequestObject) (UndoLastEventResponseObject, error)

	// (GET /api/v1/appointments)
	ListAppointments(ctx context.Context, request ListAppointmentsRequestObject) (ListAppointmentsResponseObject, error)
	// ListCompanies Alle Firmen mit Anzahl Bewerbungen
	// (GET /api/v1/companies)
	ListCompanies(ctx context.Context, request ListCompaniesRequestObject) (ListCompaniesResponseObject, error)
	// CreateCompany Firma anlegen
	// (POST /api/v1/companies)
	CreateCompany(ctx context.Context, request CreateCompanyRequestObject) (CreateCompanyResponseObject, error)
	// DeleteCompany Firma löschen (nur ohne Bewerbungen, sonst 409)
	// (DELETE /api/v1/companies/{id})
	DeleteCompany(ctx context.Context, request DeleteCompanyRequestObject) (DeleteCompanyResponseObject, error)

	// (GET /api/v1/companies/{id})
	GetCompany(ctx context.Context, request GetCompanyRequestObject) (GetCompanyResponseObject, error)
	// UpdateCompany Firma ändern (nur gesetzte Felder; "" löscht optionale Felder)
	// (PATCH /api/v1/companies/{id})
	UpdateCompany(ctx context.Context, request UpdateCompanyRequestObject) (UpdateCompanyResponseObject, error)
	// GetCv Lebenslauf lesen (leere Struktur, solange keiner gespeichert ist)
	// (GET /api/v1/cv)
	GetCv(ctx context.Context, request GetCvRequestObject) (GetCvResponseObject, error)
	// SaveCv Lebenslauf ersetzen
	// (PUT /api/v1/cv)
	SaveCv(ctx context.Context, request SaveCvRequestObject) (SaveCvResponseObject, error)
	// GetCvPdf Lebenslauf als PDF (404 ohne gespeicherten Lebenslauf, 503 wenn der PDF-Dienst fehlt)
	// (GET /api/v1/cv/pdf)
	GetCvPdf(ctx context.Context, request GetCvPdfRequestObject) (GetCvPdfResponseObject, error)
	// DeleteCvPhoto Bewerbungsfoto entfernen
	// (DELETE /api/v1/cv/photo)
	DeleteCvPhoto(ctx context.Context, request DeleteCvPhotoRequestObject) (DeleteCvPhotoResponseObject, error)
	// GetCvPhoto Bewerbungsfoto (JPEG); 404, solange keines gespeichert ist
	// (GET /api/v1/cv/photo)
	GetCvPhoto(ctx context.Context, request GetCvPhotoRequestObject) (GetCvPhotoResponseObject, error)
	// SaveCvPhoto Bewerbungsfoto ersetzen (JPEG, max. 1 MB)
	// (PUT /api/v1/cv/photo)
	SaveCvPhoto(ctx context.Context, request SaveCvPhotoRequestObject) (SaveCvPhotoResponseObject, error)
	// CloseCvReview Offene Optimierung abschließen bzw. Anfrage zurückziehen
	// (DELETE /api/v1/cv/review)
	CloseCvReview(ctx context.Context, request CloseCvReviewRequestObject) (CloseCvReviewResponseObject, error)
	// GetCvReview Offene Optimierung (angefordert oder fertig); 404, wenn keine offen ist
	// (GET /api/v1/cv/review)
	GetCvReview(ctx context.Context, request GetCvReviewRequestObject) (GetCvReviewResponseObject, error)
	// RequestCvReview Optimierung anfordern (409 ohne gespeicherten Lebenslauf oder bei offener Optimierung)
	// (POST /api/v1/cv/review)
	RequestCvReview(ctx context.Context, request RequestCvReviewRequestObject) (RequestCvReviewResponseObject, error)

	// (GET /api/v1/deadlines)
	ListDeadlines(ctx context.Context, request ListDeadlinesRequestObject) (ListDeadlinesResponseObject, error)

	// (GET /api/v1/stats/funnel)
	GetFunnel(ctx context.Context, request GetFunnelRequestObject) (GetFunnelResponseObject, error)

	// (GET /api/v1/stats/summary)
	GetSummary(ctx context.Context, request GetSummaryRequestObject) (GetSummaryResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

